script:
export const meta = {
  name: 'leak-vision-verify',
  description: 'Vision-verify the regenerated previously-leaked assets are now IP-clean (no real brand/logo/trademark/trade-dress/real-venue/real-person-caption in the pixels)',
  phases: [{ title: 'Vision verify' }],
}
const BASE = '/Users/dhiren/Downloads/Deccan/Adobe-Freelance-Leads'
const AUDIT = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/aa9e6dfc-7579-493e-a3a8-45be309ed406/scratchpad/audit_bytask.json'
const FFMPEG = BASE + '/asset_pipeline/.venv/lib/python3.9/site-packages/imageio_ffmpeg/binaries'
const IDS = args
const SCHEMA = {
  type: 'object',
  properties: {
    task_id: { type: 'string' },
    files_checked: { type: 'array', items: { type: 'string' } },
    all_clean: { type: 'boolean' },
    still_leaking: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
  required: ['task_id', 'all_clean', 'notes'],
}
const results = await parallel(IDS.map((id) => () => agent(
  `Vision-verify that task ${id}'s REGENERATED (previously brand-leaking) assets are now IP-clean.\n\n` +
  `1. Read ${AUDIT}, get the "${id}" entry's "leaked_files" — those exact files were just regenerated with a hardened anti-brand prompt.\n` +
  `2. For each file in ${BASE}/input_assets_v3/${id}/assets/:\n` +
  `   - If it is an image (.jpg/.png): open/READ it and LOOK at the pixels.\n` +
  `   - If it is a video (.mp4/.mov): extract a frame first, e.g. run bash \`ls ${FFMPEG}\` to find the ffmpeg binary, then \`<ffmpeg> -y -i <video> -vf "select=eq(n\\,30)" -vframes 1 /tmp/${id}_frame.jpg\`, then READ that frame.\n` +
  `3. Judge STRICTLY: is there ANY real-world brand name, logo, wordmark, trademark, trade dress (e.g. Marshall amp livery, a real deli's branded paper), real venue signage at a real address, or a burned-in real-person name/caption? The task's OWN fictional brand appearing is CORRECT and fine.\n` +
  `Return files_checked, all_clean (true only if every regenerated file is free of real-world IP), still_leaking (any file that still shows a real brand + what), and a one-line note.`,
  { agentType: 'general-purpose', phase: 'Vision verify', label: `vv:${id}`, schema: SCHEMA }
)))
const r = results.filter(Boolean)
return {
  tasks: r.length,
  all_clean_tasks: r.filter(x => x.all_clean).length,
  still_leaking: r.filter(x => !x.all_clean).map(x => ({ id: x.task_id, files: x.still_leaking, notes: x.notes })),
}
